1	import { useCallback } from "react";
2	
3	import * as api from "@/features/sync/api/git-api";
4	import { yieldToUi } from "@/shared/lib/notes";
5	import { getErrorMessage } from "@typenotes/shared/errors";
6	import type {
7	  GitCommitHistoryEntry,
8	  GitSyncAction,
9	  GitSyncStatus,
10	  ProfileSyncSettings,
11	} from "@typenotes/shared/types";
12	
13	type UseGitSyncWorkflowsArgs = {
14	  gitStatus: GitSyncStatus | null;
15	  gitSyncAction: GitSyncAction;
16	  setGitStatus: (status: GitSyncStatus | null) => void;
17	  setGitSyncAction: (action: GitSyncAction) => void;
18	  setGitSyncError: (error: string | null) => void;
19	  setGitCommitHistory: (history: GitCommitHistoryEntry[]) => void;
20	  setGitHistoryBusy: (busy: boolean) => void;
21	  setGitHistoryError: (error: string | null) => void;
22	  syncSettings: ProfileSyncSettings;
23	  updateSyncSettings: (patch: Partial<ProfileSyncSettings>) => Promise<void>;
24	};
25	
26	export function useGitSyncWorkflows({
27	  gitStatus,
28	  gitSyncAction,
29	  setGitStatus,
30	  setGitSyncAction,
31	  setGitSyncError,
32	  setGitCommitHistory,
33	  setGitHistoryBusy,
34	  setGitHistoryError,
35	  syncSettings,
36	  updateSyncSettings,
37	}: UseGitSyncWorkflowsArgs) {
38	  const gitSyncBusy = gitSyncAction !== "idle";
39	
40	  const refreshGitStatus = useCallback(async () => {
41	    setGitSyncAction("refresh");
42	    await yieldToUi();
43	    try {
44	      const status = await api.getGitStatus();
45	      setGitStatus(status);
46	      setGitSyncError(null);
47	    } catch (error) {
48	      setGitSyncError(getErrorMessage(error));
49	    } finally {
50	      setGitSyncAction("idle");
51	    }
52	  }, [setGitStatus, setGitSyncAction, setGitSyncError]);
53	
54	  const refreshGitHistory = useCallback(
55	    async (limit = 40) => {
56	      setGitHistoryBusy(true);
57	      await yieldToUi();
58	      try {
59	        const history = await api.getGitHistory(limit);
60	        setGitCommitHistory(history);
61	        setGitHistoryError(null);
62	      } catch (error) {
63	        setGitHistoryError(getErrorMessage(error));
64	        setGitCommitHistory([]);
65	      } finally {
66	        setGitHistoryBusy(false);
67	      }
68	    },
69	    [setGitCommitHistory, setGitHistoryBusy, setGitHistoryError]
70	  );
71	
72	  const connectGitRepo = useCallback(async () => {
73	    const remoteUrl = syncSettings.gitRemoteUrl.trim();
74	    const branch = syncSettings.gitBranch.trim();
75	    if (!remoteUrl) {
76	      setGitSyncError("Remote repository URL is required.");
77	      return;
78	    }
79	    setGitSyncAction("connect");
80	    await yieldToUi();
81	    try {
82	      const status = await api.connectGitRepo(
83	        remoteUrl,
84	        branch || undefined,
85	        syncSettings.gitUsername.trim() || undefined,
86	        syncSettings.gitPassword || undefined
87	      );
88	      setGitStatus(status);
89	      setGitSyncError(null);
90	      void refreshGitHistory();
91	    } catch (error) {
92	      setGitSyncError(getErrorMessage(error));
93	    } finally {
94	      setGitSyncAction("idle");
95	    }
96	  }, [
97	    refreshGitHistory,
98	    setGitStatus,
99	    setGitSyncAction,
100	    setGitSyncError,
101	    syncSettings,
102	  ]);
103	
104	  const gitPull = useCallback(
105	    async (opts?: { onAfterPull?: () => Promise<void> }) => {
106	      const branch = syncSettings.gitBranch.trim();
107	      setGitSyncAction("pull");
108	      await yieldToUi();
109	      try {
110	        const status = await api.gitPull(
111	          branch || undefined,
112	          syncSettings.gitUsername.trim() || undefined,
113	          syncSettings.gitPassword || undefined
114	        );
115	        setGitStatus(status);
116	        setGitSyncError(null);
117	        updateSyncSettings({ lastSuccessfulSyncAt: new Date().toISOString() });
118	        void refreshGitHistory();
119	        if (opts?.onAfterPull) {
120	          await opts.onAfterPull();
121	        }
122	      } catch (error) {
123	        setGitSyncError(getErrorMessage(error));
124	      } finally {
125	        setGitSyncAction("idle");
126	      }
127	    },
128	    [
129	      refreshGitHistory,
130	      setGitStatus,
131	      setGitSyncAction,
132	      setGitSyncError,
133	      syncSettings,
134	      updateSyncSettings,
135	    ]
136	  );
137	
138	  const gitPush = useCallback(async () => {
139	    const branch = syncSettings.gitBranch.trim();
140	    const commitMessage = syncSettings.gitCommitMessage.trim();
141	    setGitSyncAction("push");
142	    await yieldToUi();
143	    try {
144	      const statusBeforePush = await api.getGitStatus();
145	      setGitStatus(statusBeforePush);
146	      if (!statusBeforePush.push_required) {
147	        setGitSyncError(null);
148	        void refreshGitHistory();
149	        return;
150	      }
151	      const status = await api.gitPush(
152	        commitMessage || undefined,
153	        branch || undefined,
154	        syncSettings.gitUsername.trim() || undefined,
155	        syncSettings.gitPassword || undefined
156	      );
157	      setGitStatus(status);
158	      setGitSyncError(null);
159	      updateSyncSettings({ lastSuccessfulSyncAt: new Date().toISOString() });
160	      void refreshGitHistory();
161	    } catch (error) {
162	      setGitSyncError(getErrorMessage(error));
163	    } finally {
164	      setGitSyncAction("idle");
165	    }
166	  }, [
167	    refreshGitHistory,
168	    setGitStatus,
169	    setGitSyncAction,
170	    setGitSyncError,
171	    syncSettings,
172	    updateSyncSettings,
173	  ]);
174	
175	  // One-tap sync: connect (if needed) -> push local work -> pull/merge remote
176	  // -> push the merged result. The sequence matches the existing manual
177	  // controls, but it absorbs the expected first-push rejection when another
178	  // device has already advanced the remote branch.
179	  const syncNow = useCallback(
180	    async (opts?: {
181	      remote?: string;
182	      branch?: string;
183	      onAfterPull?: () => Promise<void>;
184	    }) => {
185	      // An explicit remote from discovery wins over the stored setting.
186	      const remoteUrl = (opts?.remote ?? syncSettings.gitRemoteUrl).trim();
187	      if (!remoteUrl) {
188	        setGitSyncError("Remote repository URL is required.");
189	        return;
190	      }
191	      const branch = (opts?.branch ?? syncSettings.gitBranch).trim() || undefined;
192	      const username = syncSettings.gitUsername.trim() || undefined;
193	      const password = syncSettings.gitPassword || undefined;
194	      const message = syncSettings.gitCommitMessage.trim() || undefined;
195	
196	      if (opts?.remote) {
197	        void updateSyncSettings({
198	          gitRemoteUrl: opts.remote,
199	          ...(opts.branch ? { gitBranch: opts.branch } : {}),
200	        });
201	      }
202	
203	      setGitSyncAction("sync");
204	      await yieldToUi();
205	      try {
206	        let status = gitStatus;
207	        if (!status?.repo_initialized) {
208	          status = await api.connectGitRepo(remoteUrl, branch, username, password);
209	          setGitStatus(status);
210	        }
211	
212	        try {
213	          const beforeFirstPush = await api.getGitStatus();
214	          if (beforeFirstPush.push_required) {
215	            status = await api.gitPush(message, branch, username, password);
216	            setGitStatus(status);
217	          }
218	        } catch {
219	          // A rejected first push is fine here: the pull below reconciles it.
220	        }
221	
222	        const beforePull = await api.getGitStatus();
223	        setGitStatus(beforePull);
224	        if (!beforePull.has_uncommitted_changes) {
225	          status = await api.gitPull(branch, username, password);
226	          setGitStatus(status);
227	          if (opts?.onAfterPull) {
228	            await opts.onAfterPull();
229	          }
230	        }
231	
232	        const beforeFinalPush = await api.getGitStatus();
233	        setGitStatus(beforeFinalPush);
234	        if (beforeFinalPush.push_required) {
235	          status = await api.gitPush(message, branch, username, password);
236	          setGitStatus(status);
237	        }
238	
239	        setGitSyncError(null);
